INSERT INTO public.support_auto_reply_templates (name, keywords, body, priority) VALUES
('Покупка без тарифа', '["купил", "оплатил", "купил подписку"]', 'УТОЧНИТЕ ПОЖАЛУЙСТА, КАКУЮ ПОДПИСКУ ВЫ КУПИЛИ И ЧЕРЕЗ КАКОЙ СПОСОБ ОПЛАТЫ?', 5),
('FunPay ожидание', '["funpay", "фанпей"]', 'ПРОВЕРЬТЕ, ЧТО ЗАКАЗ НА FUNPAY ОПЛАЧЕН И НЕ ОТМЕНЁН. ПРИШЛИТЕ НОМЕР ЗАКАЗА, ЕСЛИ ПРОДАВЕЦ НЕ ВЫШЕЛ НА СВЯЗЬ.', 12),
('Telegram оплата', '["telegram", "телеграм"]', 'ЕСЛИ ОПЛАТА БЫЛА ЧЕРЕЗ TELEGRAM, НАПИШИТЕ USERNAME ИЛИ НОМЕР ЗАКАЗА. ДОСТУП ВЫДАЁТ ПРОДАВЕЦ ПО ЛОГИНУ ИЛИ ЧЕРЕЗ КЛЮЧ.', 13),
('Продавец не отвечает', '["продавец не отвечает", "нет ответа", "не ответил", "устал ждать"]', 'ОЖИДАЙТЕ, ПОКА ВАМ ОТВЕТИТ ПРОДАВЕЦ И ВЫДАСТ ДОСТУП ЛИБО ПО ЛОГИНУ, ЛИБО ЧЕРЕЗ КЛЮЧ. ЕСЛИ СРОК СТАЛ СЛИШКОМ ДОЛГИМ, ПРИШЛИТЕ НОМЕР ЗАКАЗА.', 14),
('Ключ не пришёл', '["ключ не пришёл", "не получил ключ", "где ключ"]', 'КЛЮЧ ОБЫЧНО ПРИСЫЛАЕТ ПРОДАВЕЦ ПОСЛЕ ПРОВЕРКИ ОПЛАТЫ. ПРОВЕРЬТЕ ЛИЧНЫЕ СООБЩЕНИЯ И ПРИШЛИТЕ НОМЕР ЗАКАЗА.', 15),
('Base', '["base", "бейс"]', 'ТАРИФ BASE ВЫДАЁТСЯ ПОСЛЕ ПОДТВЕРЖДЕНИЯ ОПЛАТЫ ПРОДАВЦОМ. УТОЧНИТЕ СПОСОБ ОПЛАТЫ И НОМЕР ЗАКАЗА.', 20),
('Premium', '["premium", "премиум"]', 'ТАРИФ PREMIUM ВЫДАЁТСЯ ПОСЛЕ ПОДТВЕРЖДЕНИЯ ОПЛАТЫ ПРОДАВЦОМ. УТОЧНИТЕ СПОСОБ ОПЛАТЫ И НОМЕР ЗАКАЗА.', 21),
('Premium Beta', '["premium beta", "premium+beta", "бета"]', 'PREMIUM+BETA ВКЛЮЧАЕТ РАННИЙ ДОСТУП. ПОСЛЕ ОПЛАТЫ ПРОДАВЕЦ ВЫДАЁТ ДОСТУП ПО ЛОГИНУ ИЛИ КЛЮЧОМ.', 22),
('Tester', '["tester", "тестер", "тестировщик"]', 'TESTER — БЕСПЛАТНЫЙ QA-ДОСТУП ДЛЯ ПОИСКА БАГОВ. ОПИШИТЕ НАЙДЕННУЮ ПРОБЛЕМУ И ШАГИ ВОСПРОИЗВЕДЕНИЯ.', 30),
('Media', '["media", "медиа", "партнёр", "партнер"]', 'MEDIA — БЕСПЛАТНЫЙ ДОСТУП ДЛЯ МЕДИА-ПАРТНЁРОВ. ПРИШЛИТЕ ССЫЛКУ НА ПЛОЩАДКУ И КОНТАКТ ДЛЯ ПРОВЕРКИ.', 31),
('Логин для выдачи', '["по логину", "логин"]', 'ПРОДАВЕЦ МОЖЕТ ВЫДАТЬ ПОДПИСКУ ПО ЛОГИНУ. УБЕДИТЕСЬ, ЧТО ВЫ УКАЗАЛИ ИМЕННО USERNAME ВАШЕГО АККАУНТА CHROMA.', 40),
('Ошибочный ключ', '["неверный ключ", "ключ недействителен", "unknown key"]', 'ПРОВЕРЬТЕ РЕГИСТР, ПРОБЕЛЫ И ВСЕ СИМВОЛЫ КЛЮЧА. ЕСЛИ ОШИБКА ОСТАЛАСЬ, ПРИШЛИТЕ СКРИНШОТ БЕЗ ПУБЛИКАЦИИ ПОЛНОГО КЛЮЧА.', 41),
('Срок подписки', '["срок подписки", "закончилась подписка", "истекла"]', 'ПРИШЛИТЕ EMAIL АККАУНТА И НАЗВАНИЕ ТАРИФА. МЫ ПРОВЕРИМ ДАТУ ОКОНЧАНИЯ И СТАТУС АКТИВАЦИИ.', 50),
('Оплата проверяется', '["проверка оплаты", "проверяют оплату", "оплата прошла"]', 'ПОСЛЕ ПОДТВЕРЖДЕНИЯ ПЛАТЕЖА ПРОДАВЕЦ ВЫДАСТ ДОСТУП. НЕ ОТПРАВЛЯЙТЕ ПАРОЛЬ ИЛИ ПОЛНЫЕ ПЛАТЁЖНЫЕ ДАННЫЕ В ЧАТ.', 51),
('Скриншот', '["скрин", "скриншот", "screenshot"]', 'ПРИШЛИТЕ СКРИНШОТ ОШИБКИ, ЗАКРОВЕННЫЕ ПАРОЛИ И ПОЛНЫЕ ПЛАТЁЖНЫЕ ДАННЫЕ. ТАК МЫ БЫСТРЕЕ НАЙДЁМ ПРОБЛЕМУ.', 60),
('Закрытие вопроса', '["спасибо", "понятно", "всё работает", "все работает"]', 'РАДЫ, ЧТО ВОПРОС РЕШЁН. ЕСЛИ ПРОБЛЕМА ВОЗНИКНЕТ СНОВА, ОТКРОЙТЕ НОВОЕ ОБРАЩЕНИЕ.', 90),
('Безопасность', '["пароль", "пароля", "код от аккаунта"]', 'НЕ ПЕРЕДАВАЙТЕ ПАРОЛЬ, КОД ИЗ ПОЧТЫ ИЛИ ПОЛНЫЕ ПЛАТЁЖНЫЕ ДАННЫЕ. ПОДДЕРЖКА НИКОГДА ИХ НЕ ЗАПРАШИВАЕТ.', 3),
('Loader', '["loader", "лоадер", "запуск"]', 'УКАЖИТЕ ВЕРСИЮ LOADER, ВЕРСИЮ КЛИЕНТА И ТЕКСТ ОШИБКИ. ЕСЛИ ЕСТЬ ЛОГ, ПРИШЛИТЕ ТОЛЬКО ФРАГМЕНТ БЕЗ ТОКЕНОВ.', 70),
('Баг интерфейса', '["кнопка", "интерфейс", "не открывается"]', 'ОПИШИТЕ, НА КАКОЙ СТРАНИЦЕ ВОЗНИКАЕТ ПРОБЛЕМА, И ПРИШЛИТЕ СКРИНШОТ. МЫ ПЕРЕДАДИМ ИНФОРМАЦИЮ В QA.', 71),
('Ожидание ответа', '["долго отвечают", "когда ответ", "ждать ответ"]', 'ОБРАЩЕНИЕ УЖЕ В ОЧЕРЕДИ. НЕ ЗАКРЫВАЙТЕ ТИКЕТ — ОТВЕТ ПОЯВИТСЯ В ЭТОМ ЧАТЕ АВТОМАТИЧЕСКИ.', 80)
